// SetLogic replaces the registered business logic for this record only (tests); no
// arguments runs no triggers at all.
func (t *Resource) SetLogic(logic ...any) {
	for _, l := range logic {
		checkLogic(ResourceTableName, "Resource", l, resourceTrigger)
	}
	if logic == nil {
		logic = []any{}
	}
	t.logic = logic
}

func (t *Resource) registeredLogic() []any {
	if t.logic != nil {
		return t.logic
	}
	return resourceLogic
}

// runOnInsert runs the OnInsert triggers, then the field checks of the definition
func (t *Resource) runOnInsert() error {
	for _, l := range t.registeredLogic() {
		if trg, ok := l.(ResourceOnInsert); ok {
			if err := trg.OnInsert(t); err != nil {
				return err
			}
		}
	}
	return t.CheckFields()
}

