	t.Price_profit_calculation = ResourcePrice_profit_calculation(price_profit_calculationInt)
	t.Unit_price, _ = types.NewDecimalFromString(unit_priceNull.String)
	t.Vendor_no = types.NewCode(vendor_noNull.String)
