// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *Resource) SetFlowFilter(field, expr string) error {
	switch field {
	case "date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Date_filter = expr
		return nil
	case "unit_of_measure_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Unit_of_measure_filter = expr
		return nil
	case "chargeable_filter":
		if err := flowfilter.Validate(flowfilter.KindBool, expr); err != nil {
			return err
		}
		t.Chargeable_filter = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of Resource", field)
}

// GetFlowFilterFields returns the FlowFilter fields (name and flowfilter kind)
func (t *Resource) GetFlowFilterFields() []tables.FlowFilterFieldInfo {
	return []tables.FlowFilterFieldInfo{
		{Name: "date_filter", Kind: string(flowfilter.KindDate)},
		{Name: "unit_of_measure_filter", Kind: string(flowfilter.KindCode)},
		{Name: "chargeable_filter", Kind: string(flowfilter.KindBool)},
	}
}

